334: function updateHUD(s) {
335:   if (!s) return;
336:   $('#hud-night').textContent = s.custom ? 'CST' : pad(s.night);
337:   $('#hud-difficulty').textContent = DIFFICULTIES[s.difficulty]?.label || 'STANDARD';
338:   $('#hud-time').textContent = `${s.clock.hour}:${pad(s.clock.minutes)}`;
339:   $('#hud-ampm').textContent = s.clock.ampm;
340: 
341:   const dots = $$('#hour-dots i');
342:   dots.forEach((d, i) => {
343:     d.classList.toggle('done', i < s.hour);
344:     d.classList.toggle('active', i === s.hour && game.phase === 'playing');
345:   });
346: 
347:   const power = Math.max(0, Math.round(s.power));
348:   $('#hud-power').textContent = `${power}%`;
349:   const powerFill = $('#power-fill');
350:   powerFill.style.width = `${power}%`;
351:   powerFill.classList.toggle('low', power <= 40 && power > 18);
352:   powerFill.classList.toggle('critical', power <= 18);
353: 
354:   const battery = Math.max(0, Math.round(s.battery));
355:   $('#hud-battery').textContent = `${battery}%`;
356:   const batteryFill = $('#battery-fill');
357:   batteryFill.style.width = `${battery}%`;
358:   batteryFill.classList.toggle('low', battery <= 20);
359:   $('#battery-sub').textContent = s.flashlight ? 'DRAINING' : battery < 100 ? 'RECOVERING' : 'READY';
360: 
361:   const usage = 1 + (s.monitor ? 1 : 0) + (s.doors.left ? 1 : 0) + (s.doors.right ? 1 : 0) + (s.redAlert ? 1 : 0);
362:   $$('#usage-bars i').forEach((bar, i) => {
363:     bar.classList.toggle('on', i < usage);
364:     bar.classList.toggle('warn', i < usage && power <= 30);
365:   });
366:   $('#power-sub').textContent = `USAGE ${pad(usage)}`;
367: 
368:   const left = $('#btn-door-left');
369:   const right = $('#btn-door-right');
370:   left.classList.toggle('closed', s.doors.left);
371:   right.classList.toggle('closed', s.doors.right);
372:   left.classList.toggle('alert', !!s.danger.left);
373:   right.classList.toggle('alert', !!s.danger.right);
374:   left.querySelector('.door-state b').textContent = s.doors.left ? 'SEALED' : 'OPEN';
375:   right.querySelector('.door-state b').textContent = s.doors.right ? 'SEALED' : 'OPEN';
376:   $('#btn-flashlight').classList.toggle('on', s.flashlight);
377:   $('#danger-vignette').classList.toggle('on', !!(s.danger.left || s.danger.right || s.danger.vent || s.redAlert));
378:   $('#red-alert').classList.toggle('on', !!s.redAlert);
379: 
380:   if (s.monitor && game.phase === 'playing') {
381:     hudEl.classList.add('camera-open');
382:     cameraUI.classList.remove('is-hidden');
383:     cameraUI.classList.add('is-visible', 'monitor-open');
384:     updateCameraHud(s);
385:   } else if (!s.monitor) {
386:     hudEl.classList.remove('camera-open');
387:     cameraUI.classList.remove('is-visible', 'monitor-open');
388:   }
389: }
