391: function updateCameraHud(s) {
392:   if (!s) return;
393:   const def = CAMERA_DEFS[s.activeCam] || CAMERA_DEFS.stage;
394:   $('#cam-label').textContent = def.label;
395:   $('#cam-room').textContent = def.name;
396:   const time = `${s.clock.hour}:${pad(s.clock.minutes)}:${pad(Math.floor((s.hourFloat % (1 / 60)) * 3600))}`;
397:   $('#cam-clock').textContent = time;
398:   $('#cam-ampm').textContent = s.clock.ampm;
399:   $('#cam-signal').textContent = `${Math.round(s.camSignal)}%`;
400:   const frames = Math.floor((game.elapsed || 0) * 24);
401:   const f = frames % 24, secs = Math.floor(frames / 24) % 60, mins = Math.floor(frames / 1440) % 60;
402:   $('#cam-timecode').textContent = `00:${pad(mins)}:${pad(secs)}:${pad(f)}`;
403:   $('#cam-power').textContent = (s.usage || 1).toFixed(1);
404: 
405:   const activeRoom = s.activeCam;
406:   const intruders = Object.values(game.ai).filter(a =>
407:     a && a.active && a.room === activeRoom &&
408:     !(a.state === 'door' || a.state === 'retreat') &&
409:     a.state !== 'dormant'
410:   );
411:   const warning = $('#cam-warning');
412:   const isGlitch = intruders.some(a => a.id === 'muzan');
413:   warning.classList.toggle('on', intruders.length > 0 || isGlitch);
414:   warning.textContent = isGlitch ? 'SIGNAL INTERFERENCE' : 'MOTION DETECTED';
415: 
416:   let msg = 'ALL SYSTEMS NOMINAL';
417:   if (s.camSignal < 70) msg = 'SIGNAL DEGRADED';
418:   if (intruders.length) msg = `${intruders[0].id.toUpperCase()} VISIBLE`;
419:   if (s.redAlert) msg = 'MANUAL OVERRIDE';
420:   $('#cam-msg').textContent = msg;
421:   $$('.cam-map-btn').forEach(b => b.classList.toggle('is-active', b.dataset.cam === s.activeCam));
422: }
