267:     if (this.redAlert) { this.hint('The camera feed will not hold.'); return; }
268:     if (open === this.monitor) return;
269:     this.monitor = open;
270:     if (open) {
271:       this.flashlight = false;
272:       this.world.setFlashlight(false);
273:       this.camsVisited.add(this.activeCam);
274:       this.camChecks++;
275:       this.audio.cameraUp();
276:       this.cb.onCameraOpen?.({ cam: this.activeCam, monitor: this.snapshot });
277:     } else {
278:       this.audio.cameraDown();
279:       this.cb.onCameraClose?.();
280:     }
281:     this._pushState(true);
282:   }
283: 
284:   toggleMonitor() {
285:     this.setMonitor(!this.monitor);
286:   }
287: 
288:   setCamera(camKey) {
289:     if (!CAMERA_DEFS[camKey] || this.phase !== 'playing') return;
290:     if (!this.monitor) { this.setMonitor(true); }
291:     if (this.activeCam === camKey) return;
292:     this.activeCam = camKey;
293:     this.camsVisited.add(camKey);
294:     this.camChecks++;
295:     this.audio.cameraSwitch();
296:     this.cb.onCameraSwitch?.({ cam: camKey, def: CAMERA_DEFS[camKey] });
297:     this._pushState(true);
298:   }
299: 
300:   toggleFlashlight(force) {
301:     if (this.phase !== 'playing') return;
302:     const want = typeof force === 'boolean' ? force : !this.flashlight;
303:     if (want && (this.battery <= 0 || this.monitor)) {
304:       if (this.battery <= 0) this.hint('Torch cell depleted. Let it recover.');
305:       return;
306:     }
307:     if (want === this.flashlight) return;
308:     this.flashlight = want;
309:     this.world.setFlashlight(want, this.battery > 20 ? 1 : .65);
310:     this.audio.flashlight(want);
311:     this._pushState(true);
312:   }
313: 
314:   hint(text) {
315:     this.cb.onHint?.(text);
316:   }
317: 
318:   event(text, danger = false) {
319:     this.cb.onEvent?.({ text, danger, time: this.getClockLabel() });
320:   }
321: 
322:   /* ------------------------- update ------------------------- */
323:   update(dt) {
324:     dt = Math.min(dt, 0.05);
325:     this.time += dt;
326:     this._hz += dt;
327: 
328:     if (this.phase === 'menu') {
329:       this.world.update(dt, this.time, { menu: true });
330:       return;
331:     }
332: 
333:     if (this.phase === 'intro') {
334:       this.introTimer -= dt;
335:       this.world.update(dt, this.time, { hour: 0, powerOut: false, flicker: 1 });
336:       this._placeCharacters();
337:       if (this.introTimer <= 0) {
338:         this.phase = 'playing';
339:         this.cb.onIntroEnd?.();
340:         this._pushState(true);
341:       }
342:       return;
343:     }
344: 
345:     if (this.phase === 'paused') {
346:       return;
347:     }
348: 
349:     if (this.phase === 'jumpscare') {
350:       this._updateJumpscare(dt);
351:       this.world.update(dt, this.time, {
352:         hour: this.hour, powerOut: this.powerOut, flicker: 0.2, redAlert: true
353:       });
354:       return;
355:     }
356: 
357:     if (this.phase === 'gameover' || this.phase === 'victory') {
358:       this.world.update(dt * .35, this.time, {
359:         hour: this.phase === 'victory' ? 5.8 : this.hour, powerOut: false,
360:         flicker: this.phase === 'victory' ? 1 : .35, redAlert: false
361:       });
362:       return;
363:     }
364: 
365:     if (this.phase !== 'playing') return;
366: 
367:     this.elapsed += dt;
368:     this.hourFloat = this.elapsed / SECONDS_PER_HOUR;
369:     this.hour = Math.floor(this.hourFloat);
370: 
371:     if (this.hourFloat >= 6) { this._victory(); return; }
372: 
373:     if (this.hour !== this._lastHour) {
374:       this._lastHour = this.hour;
375:       this._onHour(this.hour);
376:     }
377: 
378:     this._updateResources(dt);
379:     this._updateAI(dt);
380:     this._updateMuzan(dt);
381:     this._updateCameraEffects(dt);
382: 
383:     if (this.powerOut) this._updatePowerOut(dt);
384: 
385:     this._placeCharacters();
386: 
387:     // exhaust flashlight
388:     if (this.flashlight) {
389:       this.battery = Math.max(0, this.battery - 1.25 * this.diff.battery * dt);
390:       if (this.battery <= 0) {
391:         this.flashlight = false;
392:         this.world.setFlashlight(false);
393:         this.hint('The torch dies in your hand.');
394:         this.event('Torch cell depleted.', true);
395:         this._pushState(true);
396:       }
397:       this.world.setFlashlight(true, this.battery > 20 ? 1 : .55);
398:     } else {
399:       this.battery = Math.min(100, this.battery + .22 * dt);
400:     }
401: 
402:     // camera sway/feed
403:     const security = this.monitor && !this.powerOut ? this.activeCam : null;
404:     this.world.update(dt, this.time, {
405:       security,
406:       hour: this.hour,
407:       hourFloat: this.hourFloat,
408:       powerOut: this.powerOut,
409:       redAlert: this.redAlert,
410:       monitorCam: security,
411:       timeLabel: this.getClockLabel(),
412:       power: this.power,
413:       flicker: 1
414:     });
415:     this.world.updateCamera(this.world.officeCamera, this.lookYaw, this.lookPitch);
416: 
417:     const tension = this._tensionLevel();
418:     this.audio.setTension(tension);
419:     if (this._hz > .07) {
420:       this._hz = 0;
421:       this._pushState();
422:     }
423:   }
424: 
425:   _updateResources(dt) {
426:     if (this.powerOut) return;
427:     let usage = 0.1;
428:     if (this.monitor) usage += 0.19;
429:     if (this.doors.left) usage += 0.29;
430:     if (this.doors.right) usage += 0.29;
431:     if (this.ai.inosuke?.state === 'door' && this.ai.inosuke.active) usage += 0.46;
432:     if (this.redAlert) usage += 0.7;
433:     this.usage = Math.round(usage * 10) / 10;
434:     this.power = Math.max(0, this.power - usage * this.diff.power * dt);
435:     if (this.power <= 0) this._powerOut();
436:   }
437: 
438:   _powerOut() {
439:     if (this.powerOut) return;
440:     this.powerOut = true;
441:     this.powerOutTimer = 0;
442:     this.monitor = false;
443:     this.doors.left = false;
444:     this.doors.right = false;
445:     this.world.setDoor('left', false);
446:     this.world.setDoor('right', false);
447:     this.audio.powerDown();
448:     document.body.classList.add('power-out');
449:     this.cb.onPowerOut?.();
450:     this.event('POWER FAILURE. The doors slide open. Something moves in the dark.', true);
451:     this.cb.onDanger?.({ left: false, right: false, vent: false });
452:     this.audio.setTension(1);
453:     this._pushState(true);
454:   }
455: 
456:   _updatePowerOut(dt) {
457:     this.powerOutTimer += dt;
458:     const marks = [3, 7, 11];
459:     for (const m of marks) {
460:       if (this.powerOutTimer >= m && !this[`_po${m}`]) {
461:         this[`_po${m}`] = true;
462:         if (m === 3) this.event('A chair scrapes somewhere behind you.', true);
463:         if (m === 7) { this.event('Two red eyes open at the back of the office.', true); this.audio.whisperDanger(); }
464:         if (m === 11) this.event('It is standing right behind you.', true);
465:       }
466:     }
467:     if (this.powerOutTimer > 14) {
468:       const ids = Object.keys(this.ai).filter(id => this.ai[id].active);
469:       const attacker = ids.includes('muzan') ? 'muzan' : (ids.includes('tanjiro') ? 'tanjiro' : ids[0] || 'tanjiro');
470:       this._beginJumpscare(attacker, 'power');
471:     }
472:   }
473: 
474:   _onHour(hour) {
475:     if (hour === 0) return;
476:     this.audio.hourChime(hour);
477:     const lines = {
478:       1: '1:00 AM. The building settles around you.',
479:       2: '2:00 AM. You can hear something breathing through the wall.',
480:       3: '3:00 AM. Halfway there. The cameras are starting to drift.',
481:       4: '4:00 AM. The halls have gone quiet. Too quiet.',
482:       5: '5:00 AM. One hour left. They know the sun is coming.'
483:     };
484:     this.event(lines[hour] || `${hour}:00 AM.`, hour >= 4);
485:     if (hour === 4) this.hint('The last hour is the worst. Watch every feed.');
486:     if (hour === 5) this.hint('One hour. Hold on.');
487:     this.cb.onHour?.({ hour });
488:   }
489: 
490:   /* ------------------------- AI ------------------------- */
491:   _moveDelay(ai) {
492:     const base = BASE_MOVE[ai.id] - ai.level * .16;
493:     return clamp(base * rand(.74, 1.28), 1.25, 9.5) / this.diff.ai;
494:   }
495: 
496:   _updateAI(dt) {
497:     for (const id of Object.keys(this.ai)) {
498:       const ai = this.ai[id];
499:       if (!ai.active || id === 'muzan') continue;
500:       if (ai.state === 'retreat') {
501:         ai.retreatTimer -= dt;
502:         if (ai.retreatTimer <= 0) {
503:           ai.state = 'roam';
504:           ai.moveTimer = this._moveDelay(ai) * .8;
505:           ai.announced = false;
506:         }
507:         continue;
508:       }
509: 
510:       if (ai.state === 'door') {
511:         const side = ai.room === 'westDoor' ? 'left' : 'right';
512:         if (this.doors[side]) {
513:           ai.closedTime += dt;
514:           if (ai.closedTime > .48) {
515:             this._retreat(ai, side);
516:             continue;
517:           }
518:         } else {
519:           ai.closedTime = 0;
520:         }
521:         if (id === 'inosuke' && Math.random() < dt * .38) {
522:           this.audio.bang();
523:           this.cb.onShake?.(.18);
524:         }
525:         ai.doorTimer -= dt;
526:         if (ai.doorTimer <= 0) {
527:           this._beginJumpscare(id, 'door');
528:           return;
529:         }
530:         continue;
531:       }
532: 
533:       if (ai.state === 'ventDoor') {
534:         if (this.flashlight && Math.abs(this.lookYaw) < .7) {
535:           ai.lightTimer += dt;
536:           if (ai.lightTimer > .52) {
537:             this._retreat(ai, 'vent');
538:             continue;
539:           }
540:         } else {
541:           ai.lightTimer = Math.max(0, ai.lightTimer - dt * .4);
542:         }
543:         if (this.monitor && this.activeCam === 'vent') {
544:           ai.ventSeen += dt;
545:           if (ai.ventSeen > .72) {
546:             this.event('On CAM 07, Nezuko recoils from the lens.', false);
547:             this._retreat(ai, 'vent');
548:             continue;
549:           }
550:         } else {
551:           ai.ventSeen = Math.max(0, ai.ventSeen - dt);
552:         }
553:         ai.doorTimer -= dt;
554:         if (ai.doorTimer <= 0) {
555:           this._beginJumpscare(id === 'nezuko' ? 'nezuko' : id, 'vent');
556:           return;
557:         }
558:         continue;
559:       }
560: 
561:       // roam
562:       if (ai.walkTimer > 0) ai.walkTimer -= dt;
563:       if (id === 'giyu' && !this.monitor) continue;
564:       if (id === 'tanjiro' && this.monitor && this.activeCam === ai.room) {
565:         ai.moveTimer = Math.max(ai.moveTimer, .9);
566:         continue;
567:       }
568:       let speed = 1;
569:       if (id === 'inosuke' && this.monitor && this.activeCam === ai.room) speed = 1.7;
570:       if (id === 'zenitsu') speed = 1.15;
571:       ai.moveTimer -= dt * speed;
572:       if (ai.moveTimer > 0) continue;
573: 
574:       const next = this._nextRoom(ai);
575:       if (!next) { ai.moveTimer = this._moveDelay(ai); continue; }
576:       if (next === 'westDoor' || next === 'eastDoor') {
577:         ai.room = next;
578:         ai.state = 'door';
579:         ai.doorTimer = DOOR_GRACE[id] * this.diff.grace;
580:         ai.closedTime = 0;
581:         ai.announced = true;
582:         this._arriveAtDoor(ai, next === 'westDoor' ? 'left' : 'right');
583:       } else if (next === 'vent') {
584:         ai.room = 'vent';
585:         ai.state = 'ventDoor';
586:         ai.doorTimer = DOOR_GRACE.nezuko * this.diff.grace;
587:         ai.lightTimer = 0;
588:         ai.ventSeen = 0;
589:         this._arriveAtVent(ai);
590:       } else {
591:         ai.room = next;
592:         ai.state = 'roam';
593:         ai.walkTimer = 1.4;
594:         ai.moveTimer = this._moveDelay(ai);
595:       }
596:     }
597:   }
598: 
599:   _nextRoom(ai) {
600:     const r = ai.room;
601:     switch (ai.id) {
602:       case 'tanjiro':
603:         if (r === 'stage') return 'dining';
604:         if (r === 'dining') return 'west';
605:         if (r === 'west') return 'westDoor';
606:         return 'west';
607:       case 'nezuko':
608:         if (r === 'dining') return 'vent';
609:         if (r === 'vent') return 'vent';
610:         return 'dining';
611:       case 'zenitsu':
612:         if (r === 'stage' || r === 'dining') return Math.random() < .5 ? 'west' : 'east';
613:         if (r === 'west') return 'westDoor';
614:         if (r === 'east') return 'eastDoor';
615:         return Math.random() < .5 ? 'west' : 'east';
616:       case 'inosuke':
617:         if (r === 'dining' || r === 'east') return 'eastDoor';
618:         return 'dining';
619:       case 'giyu':
620:         if (r === 'west') return 'westDoor';
621:         return 'west';
622:       default:
623:         return null;
624:     }
625:   }
626: 
627:   _arriveAtDoor(ai, side) {
628:     const whisper = CHARACTERS[ai.id].hint;
629:     this.event(whisper, true);
630:     this.audio.dangerCharacter(ai.id);
631:     this.cb.onDoorAlert?.({ side, on: true, character: ai.id });
632:     this.doorAlerts[side] = true;
633:     this._pushState(true);
634:   }
635: 
636:   _arriveAtVent(ai) {
637:     this.event('Nezuko is in the vent. Torch the vent or check CAM 07.', true);
638:     this.audio.dangerCharacter('nezuko');
639:     this.cb.onVentAlert?.(true);
640:     this.doorAlerts.vent = true;
641:     this._pushState(true);
642:   }
643: 
644:   _retreat(ai, side) {
645:     ai.state = 'retreat';
646:     ai.retreatTimer = rand(1.7, 2.8);
647:     ai.closedTime = 0;
648:     if (side === 'vent') {
649:       ai.room = 'dining';
650:       this.doorAlerts.vent = false;
651:       this.cb.onVentAlert?.(false);
652:       this.event('The scraping in the vent fades away.', false);
653:     } else {
654:       ai.room = side === 'left' ? 'west' : 'east';
655:       this.doorAlerts[side] = false;
656:       this.cb.onDoorAlert?.({ side, on: false, character: ai.id });
657:       this.audio.knock(side);
658:       this.event(`Something strikes the ${side} door. Then silence.`, false);
659:     }
660:     ai.announced = false;
661:     this._pushState(true);
662:   }
663: 
664:   _updateMuzan(dt) {
665:     const m = this.ai.muzan;
666:     if (!m || !m.active || this.powerOut) return;
667: 
668:     if (m.state === 'manifest') {
669:       this.redAlert = true;
670:       m.manifestTimer -= dt;
671:       const aiming = this.flashlight && Math.abs(this.lookYaw) < .5;
672:       if (aiming) {
673:         m.banish += dt;
674:         this.world.setFlashlight(true, 1.2);
675:       } else {
676:         m.banish = Math.max(0, m.banish - dt * .22);
677:       }
678:       if (m.banish >= 1.18) {
679:         m.state = 'hunt';
680:         m.banish = 0;
681:         m.nextManifest = rand(24, 34) - m.level * .55;
682:         this.redAlert = false;
683:         this.event('Muzan dissolves into the dark. He will come back.', true);
684:         this.audio.sting(.45);
685:         this.audio.powerRestored();
686:         this.cb.onMuzan?.({ on: false });
687:         this._pushState(true);
688:         return;
689:       }
690:       if (m.manifestTimer <= 0) {
691:         this._beginJumpscare('muzan', 'manifest');
692:         return;
693:       }
694:       if (m.manifestTimer < 1.1 && !m.warned) {
695:         m.warned = true;
696:         this.audio.sting(.9);
697:         this.event('He is almost on you. HOLD THE LIGHT.', true);
698:       }
699:       return;
700:     }
701: 
702:     // hunting: occasionally flickers across a wrong camera
703:     if (m.state === 'dormant' || m.state === 'hunt') {
704:       m.nextManifest -= dt;
705:       m.huntMove = (m.huntMove || 0) - dt;
706:       if (m.huntMove <= 0) {
707:         m.huntMove = rand(7, 12);
708:         const rooms = ['stage', 'dining', 'west', 'east', 'kitchen', 'storage'];
709:         m.room = rooms[(Math.random() * rooms.length) | 0];
710:       }
711:       if (this.monitor && this.activeCam === m.room) {
712:         m.glitch = Math.min(1, (m.glitch || 0) + dt * .6);
713:       } else {
714:         m.glitch = Math.max(0, (m.glitch || 0) - dt * .3);
715:       }
716:       if (m.nextManifest <= 0) {
717:         m.state = 'manifest';
718:         m.room = 'office';
719:         m.manifestTimer = clamp(4.9 - m.level * .13, 2.25, 4.9) * this.diff.grace;
720:         m.banish = 0;
721:         m.warned = false;
722:         this.monitor = false;
723:         this.flashlight = false;
724:         this.world.setFlashlight(false);
725:         this.audio.cameraDown();
726:         this.cb.onCameraClose?.();
727:         this.audio.sting(1.4);
728:         this.audio.whisperDanger();
729:         this.redAlert = true;
730:         this.event('MUZAN IS IN THE OFFICE. HOLD THE TORCH ON HIM.', true);
731:         this.cb.onMuzan?.({ on: true });
732:         this.cb.onGlitch?.(1);
733:         this._pushState(true);
734:       }
735:     }
736:   }
737: 
738:   _updateCameraEffects(dt) {
739:     const m = this.ai.muzan;
740:     let glitch = 0;
741:     if (m?.active) {
742:       if (m.state === 'manifest') glitch = 1;
743:       else if (this.monitor && m.room === this.activeCam) glitch = .45 + (m.glitch || 0) * .3;
744:     }
745:     this.camSignal = Math.round(98 - glitch * 55 - (this.powerOut ? 30 : 0));
746:     if (glitch > .4 && Math.random() < dt * 2.5) this.cb.onGlitch?.(glitch);
747:     if (this.doorAlerts.left || this.doorAlerts.right || this.doorAlerts.vent) {
748:       if (Math.random() < dt * .35) this.cb.onShake?.(.08);
749:     }
750:   }
751: 
752:   _placeCharacters() {
753:     if (this.phase === 'jumpscare' || this.phase === 'gameover' || this.phase === 'victory') return;
754:     const used = {};
755:     // hide all first
756:     for (const id of Object.keys(this.world.characters)) this.world.characters[id].visible = false;
757:     for (const id of Object.keys(this.ai)) {
758:       const ai = this.ai[id];
759:       if (!ai.active) continue;
760:       let room = ai.room;
761:       let mode = ai.state === 'door' || ai.state === 'ventDoor' ? 'menace' : (ai.walkTimer > 0 ? 'walk' : 'idle');
762:       if (id === 'muzan') {
763:         if (ai.state === 'manifest') { room = 'office'; mode = 'menace'; }
764:         else if (ai.state === 'hunt' || ai.state === 'dormant') {
765:           if (!this.monitor || this.activeCam !== ai.room) { continue; }
766:           mode = 'idle';
767:         } else continue;
768:       }
769:       if (room === 'dormant') continue;
770:       if (room === 'westDoor' && this.doors.left) continue;
771:       if (room === 'eastDoor' && this.doors.right) continue;
772:       if (room === 'vent' && ai.state === 'ventDoor') mode = 'crawl';
773:       const slot = used[room] || 0;
774:       used[room] = slot + 1;
775:       this.world.setCharacterPlacement(id, room, slot, true, mode);
776:     }
777:     this.doorAlerts.left = Object.values(this.ai).some(a => a.active && a.state === 'door' && a.room === 'westDoor');
778:     this.doorAlerts.right = Object.values(this.ai).some(a => a.active && a.state === 'door' && a.room === 'eastDoor');
779:     this.doorAlerts.vent = !!(this.ai.nezuko?.active && this.ai.nezuko.state === 'ventDoor');
780:   }
781: 
782:   _tensionLevel() {
783:     let t = .08;
784:     if (this.monitor) t += .08;
785:     if (this.doorAlerts.left || this.doorAlerts.right) t = .76;
786:     if (this.doorAlerts.vent) t = Math.max(t, .68);
787:     if (this.ai.giyu?.active && this.monitor) t += .08;
788:     if (this.ai.inosuke?.state === 'door') t = Math.max(t, .9);
789:     if (this.ai.muzan?.state === 'manifest') t = 1;
790:     if (this.powerOut) t = 1;
791:     return clamp(t * this.diff.tension, 0, 1);
792:   }
793: 
794:   _updateJumpscare(dt) {
795:     this.jumpscareTimer += dt;
796:     const c = this.world.characters[this.jumpscareId];
797:     if (c) {
798:       const t = this.jumpscareTimer;
799:       const rush = 1 - Math.pow(1 - Math.min(1, t / .62), 3);
800:       c.position.z = -0.8 + rush * 2.95;
801:       c.position.x = Math.sin(t * 37) * .035;
802:       c.position.y = (this.jumpscareId === 'nezuko' ? -.05 : 0) + Math.sin(t * 19) * .012;
803:       c.rotation.z = Math.sin(t * 21) * .055;
804:       c.rotation.x = -0.03;
805:       c.userData.mode = 'jumpscare';
806:       if (this.jumpscareLight) {
807:         this.jumpscareLight.position.set(0, 1.72, c.position.z + .62);
808:         this.jumpscareLight.intensity = 13 + Math.sin(t * 24) * 4;
809:       }
810:     }
811:     if (this.jumpscareTimer > .1 && this.jumpscareTimer < .95) {
812:       this.world.officeCamera.rotation.z = Math.sin(this.jumpscareTimer * 43) * .035;
813:       this.world.officeCamera.rotation.x = 0.012 + Math.sin(this.jumpscareTimer * 31) * .012;
