281: function makeClockTexture() {
282:   return canvasTexture(256, 256, (ctx, w, h) => {
283:     ctx.fillStyle = '#0b0c0b'; ctx.fillRect(0, 0, w, h);
284:     ctx.strokeStyle = '#c8bda5'; ctx.lineWidth = 4; ctx.beginPath(); ctx.arc(w / 2, h / 2, 108, 0, Math.PI * 2); ctx.stroke();
285:     ctx.fillStyle = '#d8ceb8'; ctx.textAlign = 'center'; ctx.font = 'bold 24px monospace';
286:     for (let i = 0; i < 12; i++) {
287:       const a = (i / 12) * Math.PI * 2 - Math.PI / 2;
288:       ctx.fillText(String(i === 0 ? 12 : i), w / 2 + Math.cos(a) * 82, h / 2 + Math.sin(a) * 82 + 8);
289:     }
290:     ctx.strokeStyle = '#b8212b'; ctx.lineWidth = 6; ctx.beginPath(); ctx.moveTo(w / 2, h / 2); ctx.lineTo(w / 2, h / 2 - 45); ctx.stroke();
291:     ctx.strokeStyle = '#d8ceb8'; ctx.lineWidth = 3; ctx.beginPath(); ctx.moveTo(w / 2, h / 2); ctx.lineTo(w / 2 + 52, h / 2 + 14); ctx.stroke();
292:     ctx.fillStyle = '#b8212b'; ctx.beginPath(); ctx.arc(w / 2, h / 2, 7, 0, Math.PI * 2); ctx.fill();
293:     ctx.font = '14px monospace'; ctx.fillStyle = '#817967'; ctx.fillText('WISTERIA', w / 2, h - 42);
294:   });
295: }
