297: function makeGrilleTexture() {
298:   return canvasTexture(256, 256, (ctx, w, h) => {
299:     ctx.fillStyle = '#171a19'; ctx.fillRect(0, 0, w, h);
300:     ctx.strokeStyle = '#5c5b52'; ctx.lineWidth = 8;
301:     for (let i = 0; i < 5; i++) {
302:       ctx.beginPath(); ctx.moveTo(20, 28 + i * 48); ctx.lineTo(w - 20, 28 + i * 48); ctx.stroke();
303:     }
304:     ctx.strokeStyle = '#2c2d29'; ctx.lineWidth = 10; ctx.strokeRect(10, 10, w - 20, h - 20);
305:   });
