308: function makeDoorTexture() {
309:   return canvasTexture(256, 512, (ctx, w, h) => {
310:     ctx.fillStyle = '#333634'; ctx.fillRect(0, 0, w, h);
311:     for (let y = 0; y < h; y += 24) {
312:       ctx.fillStyle = y % 48 === 0 ? 'rgba(230,220,190,.055)' : 'rgba(0,0,0,.2)';
313:       ctx.fillRect(0, y, w, 11);
314:     }
315:     ctx.strokeStyle = 'rgba(190,180,155,.18)'; ctx.lineWidth = 5;
316:     ctx.strokeRect(14, 14, w - 28, h - 28);
317:     for (let i = 0; i < 20; i++) {
318:       ctx.fillStyle = `rgba(120,48,25,${Math.random() * .12})`;
319:       ctx.fillRect(Math.random() * w, Math.random() * h, 2 + Math.random() * 12, 2 + Math.random() * 5);
320:     }
321:     noise(ctx, w, h, 400, .1);
322:   }, 1, 1);
323: }
