1180:   update(dt, time, state = {}) {
1181:     this.time += dt;
1182:     this.menuTime += dt;
1183:     const t = this.time;
1184: 
1185:     // character rigs
1186:     for (const id of Object.keys(this.characters)) {
1187:       const c = this.characters[id];
1188:       if (c.visible) animateCharacter(c, t, c.userData.mode || 'idle');
1189:     }
1190: 
1191:     // fan
1192:     if (this.fanRotor) this.fanRotor.rotation.z += dt * 14;
1193: 
1194:     // menu drift
1195:     if (this.menuMode) {
1196:       this.menuCamera.position.x = Math.sin(t * .12) * .7;
1197:       this.menuCamera.position.y = 2.28 + Math.sin(t * .19) * .035;
1198:       this.menuCamera.lookAt(0, 1.38, -29);
1199:       if (this.stageLights) {
1200:         this.stageLights.forEach((l, i) => {
1201:           l.intensity = 22 + Math.sin(t * .7 + i * 2) * 5;
1202:           l.color.setHex(i === 1 ? 0xd94242 : 0xffd9a4);
1203:         });
1204:       }
1205:     } else if (state.security) {
1206:       this.setActiveCamera(state.security);
1207:     }
1208: 
1209:     // door motion
1210:     ['left', 'right'].forEach(side => {
1211:       const target = this._doorTarget[side] || 0;
1212:       const cur = this._doorProgress[side] || 0;
1213:       const next = cur + (target - cur) * Math.min(1, dt * 8.5);
1214:       this._doorProgress[side] = next;
1215:       const door = this.officeDoors[side];
1216:       if (door) door.position.y = 4.70 - next * 3.12;
1217:       const led = side === 'left' ? this.ledL : this.ledR;
1218:       if (led && led.material) {
1219:         led.material.color.setHex(target > .5 ? 0xff3b3b : 0x8effa8);
1220:         led.material.emissive.setHex(target > .5 ? 0x9a0810 : 0x2b9c4c);
1221:         led.material.emissiveIntensity = target > .5 ? 2.2 : 1.5;
1222:       }
1223:     });
1224: 
1225:     // office light random Flicker
1226:     if (!state.powerOut) {
1227:       const chance = state.hour >= 4 ? .07 : .025;
1228:       if (Math.random() < chance * dt * 60) this._flicker = Math.random() < .35 ? .12 : .7;
1229:       this._flicker += (1 - this._flicker) * Math.min(1, dt * 6);
1230:     } else {
1231:       this._flicker = 0;
1232:     }
1233:     if (this.officeLightMesh) {
1234:       const glow = state.powerOut ? 0 : this._flicker;
1235:       this.officeLightMesh.material.emissiveIntensity = glow * 1.8;
1236:     }
1237:     if (!state.menu) {
1238:       this.setOfficeLighting({
1239:         powerOut: !!state.powerOut,
1240:         flicker: this._flicker,
1241:         hour: state.hour || 0,
1242:         redAlert: !!state.redAlert
1243:       });
1244:     }
1245: 
1246:     // hall flicker
1247:     if (this.flickerWest) {
1248:       const f = (Math.sin(t * 17.3) > .72 ? .14 : 1) * (Math.random() > .985 ? .2 : 1);
1249:       this.flickerWest.material.emissiveIntensity = 1.8 * f;
1250:     }
1251:     if (this.flickerEast) {
1252:       const f = (Math.sin(t * 13.7 + 1) > .82 ? .1 : 1);
1253:       this.flickerEast.material.emissiveIntensity = 1.8 * f;
1254:     }
1255:     if (this.storageBulb) {
1256:       const f = Math.random() > .96 ? .1 : (0.85 + Math.sin(t * 3) * .15);
1257:       this.storageBulb.material.emissiveIntensity = 1.8 * f;
1258:       this.storageLight.intensity = 2.6 * f;
1259:     }
1260:     if (this.kitchenRed) this.kitchenRed.intensity = 1.2 + Math.sin(t * 2.4) * .3;
1261:     if (this.emergencyLight) this.emergencyLight.intensity = (state.powerOut ? 2.4 : 1.2) + Math.sin(t * 1.1) * .2;
1262: 
1263:     // dust drift
1264:     if (this.dustSystems) {
1265:       for (const d of this.dustSystems) {
1266:         const arr = d.positions;
1267:         for (let i = 0; i < arr.length; i += 3) {
1268:           arr[i + 1] += ((Math.sin(t * .25 + i) * .5 + .5) - .5) * dt * .06;
1269:           arr[i] += Math.sin(t * .18 + i * .3) * dt * .012;
1270:           if (arr[i + 1] > 4) arr[i + 1] = .4;
1271:         }
1272:         d.points.geometry.attributes.position.needsUpdate = true;
1273:       }
1274:     }
1275:     if (this.petals) this.petals.rotation.y += dt * .006;
1276: 
1277:     // monitor drawing at 5fps (canvas upload is intentionally throttled)
1278:     if (this.monitorCtx && time - this._lastMonitorDraw > .20) {
1279:       this._lastMonitorDraw = time;
1280:       this._drawMonitor(state);
1281:     }
1282: 
1283:     // wall clock
1284:     if (time - this._lastClockDraw > 1) {
1285:       this._lastClockDraw = time;
1286:       this._updateClock(state.hourFloat || 0);
1287:     }
1288:   }
