1290:   _drawMonitor(state) {
1291:     const ctx = this.monitorCtx;
1292:     const w = this.monitorCanvas.width, h = this.monitorCanvas.height;
1293:     ctx.fillStyle = '#050c09'; ctx.fillRect(0, 0, w, h);
1294:     // static (pre-rendered tiles)
1295:     if (this.monitorNoise) {
1296:       ctx.drawImage(this.monitorNoise[this._noiseIndex++ % this.monitorNoise.length], 0, 0);
1297:     }
1298:     // camera window
1299:     ctx.strokeStyle = 'rgba(104,210,164,.28)'; ctx.lineWidth = 2;
1300:     ctx.strokeRect(24, 22, w - 48, h - 80);
1301:     ctx.fillStyle = 'rgba(87,180,141,.9)';
1302:     ctx.font = 'bold 21px monospace';
1303:     ctx.fillText(`CAM 0${state.monitorCam ? CAMERA_DEFS[state.monitorCam]?.index || 1 : 1}`, 40, 52);
1304:     ctx.font = '13px monospace';
1305:     ctx.fillStyle = 'rgba(100,190,155,.62)';
1306:     ctx.fillText(state.monitorCam ? CAMERA_DEFS[state.monitorCam].name : 'SHOW STAGE', 40, 74);
1307:     // crosshair
1308:     ctx.strokeStyle = 'rgba(93,210,160,.35)';
1309:     ctx.beginPath(); ctx.moveTo(w / 2 - 20, h / 2); ctx.lineTo(w / 2 + 20, h / 2); ctx.moveTo(w / 2, h / 2 - 20); ctx.lineTo(w / 2, h / 2 + 20); ctx.stroke();
1310:     // bars
1311:     ctx.fillStyle = 'rgba(70,160,124,.55)';
1312:     ctx.fillRect(24, h - 44, 150, 9);
1313:     ctx.fillStyle = 'rgba(70,160,124,.2)';
1314:     ctx.fillRect(24, h - 44, 300, 9);
1315:     ctx.fillStyle = 'rgba(160,230,200,.55)';
1316:     ctx.font = '11px monospace';
1317:     ctx.fillText(`${state.timeLabel || '12:00 AM'}  ·  PWR ${Math.round(state.power ?? 100)}%`, 24, h - 17);
1318:     if (state.monitorCam) ctx.fillText('LIVE FEED', w - 126, h - 17);
1319:     else ctx.fillText('MONITOR STANDBY', w - 184, h - 17);
1320:     this.monitorTexture.needsUpdate = true;
1321:   }
