1323:   _updateClock(hourFloat) {
1324:     const totalMinutes = (hourFloat + 0) * 60;
1325:     const hh = Math.floor(totalMinutes / 60) % 12 || 12;
1326:     const mm = Math.floor(totalMinutes % 60);
1327:     const ctx = this.clockTex.image.getContext('2d');
1328:     const w = 256, h = 256;
1329:     ctx.fillStyle = '#0b0c0b'; ctx.fillRect(0, 0, w, h);
1330:     ctx.strokeStyle = '#c8bda5'; ctx.lineWidth = 4; ctx.beginPath(); ctx.arc(128, 128, 108, 0, Math.PI * 2); ctx.stroke();
1331:     ctx.fillStyle = '#d8ceb8'; ctx.textAlign = 'center'; ctx.font = 'bold 24px monospace';
1332:     for (let i = 0; i < 12; i++) {
1333:       const a = (i / 12) * Math.PI * 2 - Math.PI / 2;
1334:       ctx.fillText(String(i === 0 ? 12 : i), 128 + Math.cos(a) * 82, 128 + Math.sin(a) * 82 + 8);
1335:     }
1336:     const hourAngle = ((hh % 12) + mm / 60) / 12 * Math.PI * 2 - Math.PI / 2;
1337:     const minAngle = (mm / 60) * Math.PI * 2 - Math.PI / 2;
1338:     ctx.strokeStyle = '#b8212b'; ctx.lineWidth = 6; ctx.beginPath(); ctx.moveTo(128, 128); ctx.lineTo(128 + Math.cos(hourAngle) * 48, 128 + Math.sin(hourAngle) * 48); ctx.stroke();
1339:     ctx.strokeStyle = '#d8ceb8'; ctx.lineWidth = 3; ctx.beginPath(); ctx.moveTo(128, 128); ctx.lineTo(128 + Math.cos(minAngle) * 70, 128 + Math.sin(minAngle) * 70); ctx.stroke();
1340:     ctx.fillStyle = '#b8212b'; ctx.beginPath(); ctx.arc(128, 128, 7, 0, Math.PI * 2); ctx.fill();
1341:     ctx.font = '14px monospace'; ctx.fillStyle = '#817967'; ctx.fillText('WISTERIA', 128, 210);
1342:     this.clockTex.needsUpdate = true;
1343:   }
