1350:   _cullRoomLights(camera) {
1351:     if (!this.lightPool.length) return;
1352:     const pos = camera.getWorldPosition(this._tmpVec2);
1353:     let nearestA = null, nearestB = null, nearestC = null;
1354:     let dA = Infinity, dB = Infinity, dC = Infinity;
1355:     for (const l of this.lightPool) {
1356:       l.getWorldPosition(this._tmpVec);
