_lookDot(dx, dy, dz) {
  const len = Math.hypot(dx, dy, dz) || 1;
  const cp = Math.cos(this.lookPitch);
  const fx = -Math.sin(this.lookYaw) * cp;
  const fy = Math.sin(this.lookPitch);
  const fz = -Math.cos(this.lookYaw) * cp;
  return (dx * fx + dy * fy + dz * fz) / len;
}
