const { chromium } = require('playwright');

const KEY = 'kimetus_nightmare_shift_save_v1';

async function run(page, opts, policy) {
  return page.evaluate(({ opts, policy }) => {
    const K = window.__KIMETSU__;
    const g = K.game;
    // Reset any previous run state.
    g.phase = 'menu';
    g.beginNight(opts);
    // Skip the intro card.
    for (let i = 0; i < 240 && g.phase === 'intro'; i++) g.update(1 / 60);
    const startHour = g.hour;
    let steps = 0;
    const events = [];
    const origEvent = g.cb.onEvent;
    g.cb.onEvent = (e) => { events.push(e.text); if (origEvent) origEvent(e); };

    const tick = () => {
      if (policy === 'perfect') {
        const m = g.ai.muzan;
        if (m && m.active && m.state === 'manifest') {
          if (g.monitor) g.setMonitor(false);
          if (!g.flashlight) g.toggleFlashlight(true);
          g.lookYaw = 0;
          g.lookPitch = 0.02;
          return;
        }
        const n = g.ai.nezuko;
        if (n && n.active && n.state === 'ventDoor') {
          if (!g.monitor) g.setMonitor(true);
          g.setCamera('vent');
          return;
        }
        const left = !!g.doorAlerts.left;
        const right = !!g.doorAlerts.right;
        if (left || right) {
          if (g.monitor) g.setMonitor(false);
          if (left && !g.doors.left) g.toggleDoor('left');
          if (!left && g.doors.left) g.toggleDoor('left');
          if (right && !g.doors.right) g.toggleDoor('right');
          if (!right && g.doors.right) g.toggleDoor('right');
          return;
        }
        if (g.monitor) g.setMonitor(false);
        if (g.flashlight) g.toggleFlashlight(false);
        if (g.doors.left) g.toggleDoor('left');
        if (g.doors.right) g.toggleDoor('right');
      }
    };

    const maxSteps = Math.ceil(6 * 35 * 60) + 300;
    while (g.phase === 'playing' && steps < maxSteps) {
      tick();
      g.update(1 / 60);
      steps++;
    }
    const ai = {};
    for (const [id, a] of Object.entries(g.ai)) {
      ai[id] = { level: a.level, active: a.active, state: a.state, room: a.room, timer: +(a.doorTimer || 0).toFixed(2) };
    }
    const out = {
      phase: g.phase,
      won: g.phase === 'victory',
      hour: +g.hourFloat.toFixed(2),
      elapsed: +g.elapsed.toFixed(1),
      power: +g.power.toFixed(1),
      battery: +g.battery.toFixed(1),
      jumpscare: g.jumpscareId,
      ai,
      events: events.slice(-8)
    };
    g.cb.onEvent = origEvent;
    g.phase = 'menu';
    return out;
  }, { opts, policy });
}

(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader'] });
  const page = await browser.newPage({ viewport: { width: 480, height: 300 }, hasTouch: false });
  await page.addInitScript((key) => {
    window.requestAnimationFrame = () => 0;
    localStorage.setItem(key, JSON.stringify({ version: 1, started: true, unlocked: 5, lastNight: 1, cleared: [1, 2, 3, 4], deaths: 0, settings: { master: 0, music: 0, sfx: 0, quality: 'low', difficulty: 'standard', reducedMotion: true, tilt: false }, custom: { ai: {} } }));
  }, KEY);
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
