  }
  const custom = { tanjiro: 20, nezuko: 20, zenitsu: 20, inosuke: 20, giyu: 20, muzan: 20 };
  const customPassive = await run(page, { night: 6, difficulty: 'nightmare', customAI: custom, custom: true }, 'none');
