  const customPerfect = await run(page, { night: 6, difficulty: 'nightmare', customAI: custom, custom: true }, 'perfect');
  console.log('custom perfect', JSON.stringify(customPerfect));

  console.log('errors', errors);
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

