19: 
20:     const tick = () => {
21:       if (policy === 'perfect') {
22:         const m = g.ai.muzan;
23:         if (m && m.active && m.state === 'manifest') {
24:           if (g.monitor) g.setMonitor(false);
25:           if (!g.flashlight) g.toggleFlashlight(true);
26:           g.lookYaw = 0;
27:           g.lookPitch = 0.02;
28:           return;
29:         }
30:         const n = g.ai.nezuko;
31:         if (n && n.active && n.state === 'ventDoor') {
32:           if (!g.monitor) g.setMonitor(true);
33:           g.setCamera('vent');
34:           return;
35:         }
36:         const left = !!g.doorAlerts.left;
37:         const right = !!g.doorAlerts.right;
38:         if (left || right) {
39:           if (g.monitor) g.setMonitor(false);
40:           if (left && !g.doors.left) g.toggleDoor('left');
41:           if (!left && g.doors.left) g.toggleDoor('left');
42:           if (right && !g.doors.right) g.toggleDoor('right');
43:           if (!right && g.doors.right) g.toggleDoor('right');
44:           return;
45:         }
46:         if (g.monitor) g.setMonitor(false);
47:         if (g.flashlight) g.toggleFlashlight(false);
48:         if (g.doors.left) g.toggleDoor('left');
49:         if (g.doors.right) g.toggleDoor('right');
50:       }
51:     };
52: 
53:     const maxSteps = Math.ceil(6 * 35 * 60) + 300;
54:     while (g.phase === 'playing' && steps < maxSteps) {
55:       tick();
56:       g.update(1 / 60);
57:       steps++;
58:     }
59:     const ai = {};
60:     for (const [id, a] of Object.entries(g.ai)) {
61:       ai[id] = { level: a.level, active: a.active, state: a.state, room: a.room, timer: +(a.doorTimer || 0).toFixed(2) };
62:     }
63:     const out = {
64:       phase: g.phase,
65:       won: g.phase === 'victory',
66:       hour: +g.hourFloat.toFixed(2),
67:       elapsed: +g.elapsed.toFixed(1),
68:       power: +g.power.toFixed(1),
69:       battery: +g.battery.toFixed(1),
70:       jumpscare: g.jumpscareId,
71:       ai,
72:       events: events.slice(-8)
73:     };
74:     g.cb.onEvent = origEvent;
75:     g.phase = 'menu';
76:     return out;
77:   }, { opts, policy });
78: }
