const { chromium } = require('playwright');
const fs = require('fs');

const OUT = '/home/runner/work/PlayGround/PlayGround/screenshots';
const KEY = 'kimetus_nightmare_shift_save_v1';
const SHOT = { timeout: 90000, animations: 'disabled' };

(async () => {
  fs.mkdirSync(OUT, { recursive: true });
  const browser = await chromium.launch({
    headless: true,
    args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader']
  });
  const page = await browser.newPage({ viewport: { width: 900, height: 560 } });
  await page.addInitScript((key) => {
    localStorage.setItem(key, JSON.stringify({
      version: 1, started: true, unlocked: 5, lastNight: 1,
      cleared: [1, 2, 3, 4], deaths: 3,
      settings: { master: .7, music: .5, sfx: .8, quality: 'low', difficulty: 'standard', reducedMotion: true, tilt: false },
      custom: { ai: { tanjiro: 12, nezuko: 9, zenitsu: 8, inosuke: 7, giyu: 6, muzan: 5 } }
    }));
  }, KEY);
  const errors = [];
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });

  const shot = async (name) => {
    await page.screenshot({ path: `${OUT}/${name}.png`, ...SHOT });
    console.log('shot', name);
  };
  const click = async (sel) => {
    await page.click(sel);
    await page.waitForTimeout(700);
  };

  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.waitForTimeout(2500);
  await page.waitForFunction(() => document.querySelector('#screen-title')?.classList.contains('is-active'), null, { timeout: 30000 });
  await shot('title');

  await click('[data-action="nights"]');
  await shot('night-select');

  await click('[data-action="custom"]');
  await shot('custom-night');

  await click('[data-action="options"]');
  await shot('options');

  await click('[data-action="howto"]');
  await shot('field-manual');

  await click('[data-action="back"]');
  await page.waitForTimeout(400);
  // start night 1 through the real UI
  await click('[data-action="continue"]');
  await page.waitForTimeout(4200); // intro card
  await shot('gameplay-office');

  // cameras
  await page.evaluate(() => window.__KIMETSU__.game.toggleMonitor());
  await page.waitForTimeout(2500);
  await shot('camera-feed');

  await page.evaluate(() => {
    const g = window.__KIMETSU__.game;
    g.setCamera('vent');
    g.ai.nezuko.state = 'ventDoor';
    g.ai.nezuko.room = 'vent';
    g.ai.nezuko.doorTimer = 999;
    g.ai.nezuko.active = true;
    g.doorAlerts.vent = true;
  });
  await page.waitForTimeout(2200);
  await shot('camera-vent-alert');

  // office with door + vent alerts
  await page.evaluate(() => {
    const g = window.__KIMETSU__.game;
    g.setMonitor(false);
    g.doorAlerts.left = true;
    g.doorAlerts.vent = true;
    g.ai.nezuko.state = 'ventDoor';
    g.ai.nezuko.doorTimer = 999;
    g._pushState(true);
  });
  await page.waitForTimeout(2200);
  await shot('gameplay-alerts');

  // Muzan manifestation
  await page.evaluate(() => {
    const g = window.__KIMETSU__.game;
    g.ai.muzan.active = true;
    g.ai.muzan.state = 'manifest';
    g.ai.muzan.manifestTimer = 99;
    g.redAlert = true;
    g.monitor = false;
    g._pushState(true);
  });
  await page.waitForTimeout(2200);
  await shot('muzan-manifest');

  // jumpscare mid-animation
  await page.evaluate(() => {
    const g = window.__KIMETSU__.game;
    g.ai.muzan.state = 'dormant';
    g.redAlert = false;
    g._beginJumpscare('tanjiro', 'door');
  });
  await page.waitForTimeout(420);
  await shot('jumpscare');

  await page.waitForTimeout(3000);
  await shot('game-over');

  // victory screen
  await page.evaluate(() => {
    const g = window.__KIMETSU__.game;
    g.phase = 'playing';
    g.elapsed = 6 * 35 + .1;
    g._victory();
  });
  await page.waitForTimeout(1400);
  await shot('victory');

  // pause screen
  await page.evaluate(() => {
    const g = window.__KIMETSU__.game;
    g.beginNight({ night: 1, difficulty: 'standard' });
  });
  await page.waitForTimeout(4200);
  await page.evaluate(() => window.__KIMETSU__.game.pause());
  await page.waitForTimeout(900);
  await shot('pause');

  // mobile / touch layout
  const mobile = await browser.newPage({ viewport: { width: 780, height: 400 }, hasTouch: true, isMobile: true });
  await mobile.goto('http://localhost:3002', { waitUntil: 'load' });
  await mobile.waitForTimeout(2500);
  await mobile.waitForFunction(() => document.querySelector('#screen-title')?.classList.contains('is-active'), null, { timeout: 30000 });
  await mobile.screenshot({ path: `${OUT}/touch-title.png`, ...SHOT });
  await mobile.click('[data-action="continue"]');
  await mobile.waitForTimeout(4500);
  await mobile.screenshot({ path: `${OUT}/touch-office.png`, ...SHOT });
  console.log('shot touch-title, touch-office');

  console.log('errors', JSON.stringify(errors, null, 2));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

