const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader'] });
  const page = await browser.newPage({ viewport: { width: 900, height: 560 } });
  page.on('pageerror', e => console.log('ERR', e.message));
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.waitForTimeout(2500);
  const info = await page.evaluate(() => {
    const K = window.__KIMETSU__, g = K.game;
    g.beginNight({ night: 1, difficulty: 'standard' });
    for (let i = 0; i < 240 && g.phase === 'intro'; i++) g.update(1 / 60);
    g._beginJumpscare('tanjiro', 'door');
    for (let i = 0; i < 20; i++) g.update(1 / 60);
    const c = K.world.characters.tanjiro;
    return {
      phase: g.phase, timer: g.jumpscareTimer,
      pos: c.position.toArray(), scale: c.scale.x, visible: c.visible,
      cam: K.world.officeCamera.position.toArray(),
      box: (() => { const b = new (c.constructor.prototype.constructor === Object ? Object : Object)(); return null; })()
    };
  });
  console.log(info);
  await page.waitForTimeout(300);
  await page.screenshot({ path: '/tmp/opencode/debug-jump.png', timeout: 60000 });
  await browser.close();
})();

