const { chromium } = require('playwright');
const fs = require('fs');

const OUT = '/home/runner/work/PlayGround/PlayGround/screenshots';
const KEY = 'kimetus_nightmare_shift_save_v1';
const SHOT = { timeout: 90000, animations: 'disabled' };

const save = {
  version: 1, started: true, unlocked: 5, lastNight: 1,
  cleared: [1, 2, 3, 4], deaths: 3,
  settings: { master: .7, music: .5, sfx: .8, quality: 'low', difficulty: 'standard', reducedMotion: true, tilt: false },
  custom: { ai: { tanjiro: 12, nezuko: 9, zenitsu: 8, inosuke: 7, giyu: 6, muzan: 5 } }
};

async function setup(browser, viewport, mobile = false) {
  const ctx = await browser.newContext({ viewport, hasTouch: mobile, isMobile: mobile });
  const page = await ctx.newPage();
  await page.addInitScript(({ key, data }) => {
    localStorage.setItem(key, JSON.stringify(data));
    // Freeze the render loop; the harness advances the simulation by hand.
    window.requestAnimationFrame = () => 0;
  }, { key: KEY, data: save });
  const errors = [];
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.waitForTimeout(2200);
  await page.evaluate(() => {
    const K = window.__KIMETSU__;
    window.__draw = () => {
      const view = K.game.getViewMode();
      const canvas = document.getElementById('webgl');
      canvas.classList.toggle('menu-mode', view === 'menu');
      canvas.classList.toggle('feed-mode', view === 'camera');
      K.world.render(K.game.getCamera());
    };
    window.__step = (n = 1) => {
      for (let i = 0; i < n; i++) K.game.update(1 / 60);
      window.__draw();
    };
    window.__draw();
  });
  return { page, ctx, errors };
}

const shot = async (page, name) => {
  await page.waitForTimeout(350);
  await page.screenshot({ path: `${OUT}/${name}.png`, ...SHOT });
  console.log('shot', name);
};

(async () => {
  fs.mkdirSync(OUT, { recursive: true });
  const browser = await chromium.launch({
    headless: true,
    args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader']
  });
  const { page, errors } = await setup(browser, { width: 900, height: 560 });
  const click = async (sel) => { await page.click(sel); await page.waitForTimeout(600); };
  const step = (n) => page.evaluate(n => window.__step(n), n);
  const draw = () => page.evaluate(() => window.__draw());

  await shot(page, 'title');

  await click('[data-action="nights"]');
  await shot(page, 'night-select');
  await click('#screen-nights [data-action="back"]');

  await click('[data-action="custom"]');
  await shot(page, 'custom-night');
  await click('#screen-custom [data-action="back"]');

  await click('[data-action="options"]');
  await shot(page, 'options');
  await click('#screen-options [data-action="back"]');

  await click('[data-action="howto"]');
  await shot(page, 'field-manual');
  await click('#screen-howto [data-action="back"]');

  // Start night 1 through the real UI.
  await click('[data-action="continue"]');
  await step(90); // intro card + first beat
  await shot(page, 'gameplay-office');

  await click('#btn-door-left');
  await page.evaluate(() => { const g = window.__KIMETSU__.game; g.lookYaw = -1.05; g.lookPitch = 0; });
  await step(2);
  await shot(page, 'office-west-door');
  await page.evaluate(() => { const g = window.__KIMETSU__.game; g.lookYaw = 1.05; g.lookPitch = 0; });
  await step(2);
  await shot(page, 'office-east-door');
  await page.evaluate(() => { const g = window.__KIMETSU__.game; g.lookYaw = 0; g.lookPitch = -0.035; });
  await step(2);

  // Camera overlay, opened through the HUD button.
  await click('#btn-camera');
  await step(2);
  await shot(page, 'camera-feed');

  await page.evaluate(() => {
    const g = window.__KIMETSU__.game;
    g.setCamera('vent');
    const n = g.ai.nezuko;
    n.active = true; n.state = 'ventDoor'; n.room = 'vent'; n.doorTimer = 999;
    g.doorAlerts.vent = true;
    g._pushState(true);
  });
  await step(2);
  await shot(page, 'camera-vent-alert');

  // Back to office with live alerts.
  await page.evaluate(() => {
    const g = window.__KIMETSU__.game;
    g.setMonitor(false);
    g.doorAlerts.left = true;
    g.doorAlerts.vent = true;
    g.ai.tanjiro.active = true;
    g.ai.tanjiro.state = 'door';
    g.ai.tanjiro.room = 'westDoor';
    g.ai.tanjiro.doorTimer = 999;
    g._pushState(true);
  });
  await step(3);
  await shot(page, 'gameplay-alerts');

  // Muzan manifests.
  await page.evaluate(() => {
    const g = window.__KIMETSU__.game;
    g.ai.muzan.active = true;
    g.ai.muzan.state = 'manifest';
    g.ai.muzan.manifestTimer = 999;
    g.redAlert = true;
    g.monitor = false;
    g._pushState(true);
  });
  await step(2);
  await shot(page, 'muzan-manifest');

  // Jumpscare, then the game-over screen.
  await page.evaluate(() => {
    const g = window.__KIMETSU__.game;
    g.ai.muzan.state = 'dormant';
    g.redAlert = false;
    g.phase = 'playing';
    g._beginJumpscare('tanjiro', 'door');
  });
  await step(22);
  await shot(page, 'jumpscare');
  await step(150);
  await shot(page, 'game-over');

  // Victory screen.
  await page.evaluate(() => {
    const g = window.__KIMETSU__.game;
    g.phase = 'playing';
    g.elapsed = 6 * 35 - 0.05;
    g.power = 64;
    g.camsVisited = new Set(['stage', 'dining', 'west', 'east', 'vent']);
    g.update(1 / 60);
  });
  await draw();
  await shot(page, 'victory');

  // Pause overlay.
  await page.evaluate(() => {
    const g = window.__KIMETSU__.game;
    g.beginNight({ night: 3, difficulty: 'nightmare' });
    for (let i = 0; i < 90; i++) g.update(1 / 60);
    g.pause();
  });
  await draw();
  await shot(page, 'pause');

  console.log('desktop errors', JSON.stringify(errors));
  await page.context().close();

  // Touch / landscape layout.
  const m = await setup(browser, { width: 780, height: 400 }, true);
  await shot(m.page, 'touch-title');
  await m.page.click('[data-action="continue"]');
  await m.page.evaluate(() => window.__step(90));
  await shot(m.page, 'touch-office');
  await m.page.click('#btn-camera');
  await m.page.evaluate(() => window.__step(2));
  await shot(m.page, 'touch-camera');
  console.log('mobile errors', JSON.stringify(m.errors));

  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

