input.content:
const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader'] });
  const page = await browser.newPage({ viewport: { width: 900, height: 560 } });
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.waitForTimeout(2200);
  const info = await page.evaluate(() => {
    const K = window.__KIMETSU__, g = K.game, w = K.world;
    g.beginNight({ night: 1, difficulty: 'standard' });
    for (let i = 0; i < 230; i++) g.update(1 / 60);
    g.lookYaw = -1.05;
    g.update(1 / 60);
    const d = w.officeDoors.right;
    return {
      phase: g.phase,
      yaw: g.lookYaw,
      camRot: w.officeCamera.rotation.toArray(),
      door: { pos: d.position.toArray(), y: d.position.y, visible: d.visible, mat: d.material.type, color: d.material.color.getHexString() },
      lights: {
        doorR: { i: w.doorLightR.intensity, pos: w.doorLightR.position.toArray(), parent: !!w.doorLightR.parent },
        doorL: { i: w.doorLightL.intensity, pos: w.doorLightL.position.toArray(), parent: !!w.doorLightL.parent },
        wall: { i: w.officeWallLight.intensity, pos: w.officeWallLight.position.toArray() },
        spot: w.officeSpot.intensity, fill: w.officeFill.intensity, flicker: w._flicker
      },
      ambient: w.scene.children.filter(o => o.isAmbientLight).map(l => l.intensity),
      hemi: w.scene.children.filter(o => o.isHemisphereLight).map(l => l.intensity)
    };
  });
  console.log(JSON.stringify(info, null, 2));
  await page.screenshot({ path: '/tmp/opencode/debug-door.png', timeout: 60000 });
  await browser.close();
})();

